// JAH demo program — runnable with: node demo.js
// Record JAH-APX18-000011 — Worked example: auditing a published figure
// Relationship graph traversal: breadth-first walk over a knowledge relationship graph.
'use strict';
var nodes = ["figure", "script-v3", "clean-data", "raw-files", "calibration", "corrected-figure"];
var edges = [["figure", "script-v3"], ["script-v3", "clean-data"], ["clean-data", "raw-files"], ["raw-files", "calibration"], ["figure", "corrected-figure"]];
var start = "figure";
var adj = {};
nodes.forEach(function (x) { adj[x] = []; });
edges.forEach(function (e2) { if (adj[e2[0]]) adj[e2[0]].push(e2[1]); });
var seen = {}; var order = []; var q = [start]; seen[start] = 1;
while (q.length) { var cur = q.shift(); order.push(cur); adj[cur].forEach(function (nx) { if (!seen[nx]) { seen[nx] = 1; q.push(nx); } }); }
console.log('start=' + start + ' visited=' + order.length + '/' + nodes.length);
console.log('bfs_order=' + order.join(' -> '));
console.log('edge_count=' + edges.length);

// JAH demo program — runnable with: node demo.js
// Record JAH-APX18-000012 — Failure modes: dark pipelines and identity collisions
// Uncertainty quantification: separates measured spread from model uncertainty.
'use strict';
var ms = [0.95, 0.93, 0.9, 0.72, 0.94, 0.95];
var modelVar = 0.004;
var mean = ms.reduce(function (a, b) { return a + b; }, 0) / ms.length;
var mvar = ms.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / ms.length;
var total = mvar + modelVar;
console.log('n=' + ms.length + ' mean=' + mean.toFixed(3));
console.log('measured_variance=' + mvar.toFixed(4) + ' (' + (100 * mvar / total).toFixed(1) + '%)');
console.log('model_variance=' + modelVar.toFixed(4) + ' (' + (100 * modelVar / total).toFixed(1) + '%)');
console.log('total_uncertainty_stddev=' + Math.sqrt(total).toFixed(4));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX18-000013 — Scaling: lineage at organizational scale
// Monte Carlo workload simulation: latency distribution under a synthetic load model.
'use strict';
var n = 2000, seed = 199;
var a = seed >>> 0;
function rnd() { a = (Math.imul(a, 1664525) + 1013904223) >>> 0; return a / 4294967296; }
var sum = 0, sum2 = 0;
for (var i = 0; i < n; i++) { var x = 80 + rnd() * 820; sum += x; sum2 += x * x; }
var mean = sum / n, variance = sum2 / n - mean * mean;
console.log('samples=' + n + ' mean_ms=' + mean.toFixed(2) + ' stddev_ms=' + Math.sqrt(variance).toFixed(2));

