// JAH demo program — runnable with: node demo.js
// Record JAH-APX18-000015 — Compounded integration and acceptance suite
// Machine-checked verification: each claimed identity is recomputed and checked.
'use strict';
var checks = [{"expr": "480-25", "expect": 455}, {"expr": "142+9", "expect": 151}, {"expr": "14*2", "expect": 28}];
